      [-0.16,0,0.16].forEach(function(v){ var p=Q(0,v); boiteOr(mob,p[0],y+0.44,p[1],1.72,0.035,0.11,fa,bois); });
      [0.62,0.76].forEach(function(hh){ var p=Q(0,0.25); boiteOr(mob,p[0],y+hh,p[1],1.72,0.1,0.03,fa,bois); });
