  U:{w:0.72, t:[['l',0.105,0.895,0.105,0.36],['a',0.36,0.36,0.255,0.255,180,360],['l',0.615,0.36,0.615,0.895]]},
  X:{w:0.78, t:[['l',0.105,0.895,0.675,0.105],['l',0.105,0.105,0.675,0.895]]},
  S:{w:0.70, t:[['a',0.35,0.70,0.245,0.195,25,270],['a',0.35,0.30,0.245,0.195,90,-155]]},
  O:{w:0.80, t:[['a',0.40,0.5,0.295,0.395,0,360]]},
  F:{w:0.62, t:[['l',0.105,0.105,0.105,0.895],['l',0.105,0.895,0.58,0.895],['l',0.105,0.52,0.50,0.52]]},
  I:{w:0.21, t:[['l',0.105,0.105,0.105,0.895]]},
  C:{w:0.74, t:[['a',0.40,0.5,0.295,0.395,42,318]]},
  E:{w:0.62, t:[['l',0.105,0.105,0.105,0.895],['l',0.105,0.895,0.58,0.895],['l',0.105,0.52,0.50,0.52],['l',0.105,0.105,0.58,0.105]]},
  R:{w:0.70, t:[['l',0.105,0.105,0.105,0.895],['l',0.105,0.895,0.40,0.895],['a',0.40,0.70,0.195,0.195,90,-90],['l',0.40,0.505,0.105,0.505],['l',0.34,0.505,0.63,0.105]]},
