/* ===== 23 bis. murs des maisons infranchissables ; rubalise nouée aux deux montants ===== */
/* Murs : la grille de collision (cases de 2 m) laissait passer partout à
   moins de 2,4 m du tracé et sur toute la largeur des rues, et rognait les
   angles des bâtiments : on entrait dans les maisons. Chaque bâtiment posé
   devient aussi un obstacle exact (son contour, celui qui est dessiné) dans
   la liste des obstacles de la section 22 : on glisse le long des façades.
   Seuls les bâtiments que le tracé traverse exprès (passage couvert,
   portail) restent ouverts.
   Rubalise : elle n'est plus nouée au milieu de la barrière mais aux deux
   montants, un peu sous l'angle supérieur ; entre les deux montants, elle
   longe la barrière. Elle arrive sur le montant le plus proche de la
   barrière précédente et repart de l'autre. */

/* ----- les contours des bâtiments, au fil de leur construction ----- */
var MURS23B={polys:[], idx:null, C:20, cleTrace:'', marge:0.18};
var _marquer23b=marquerPoly;
marquerPoly=function(pts){
  _marquer23b(pts);
  if(pts && pts.length>=6){
    var x0=1e9, x1=-1e9, z0=1e9, z1=-1e9;
    for(var i=0;i<pts.length;i+=2){ x0=Math.min(x0,pts[i]); x1=Math.max(x1,pts[i]); z0=Math.min(z0,pts[i+1]); z1=Math.max(z1,pts[i+1]); }
    MURS23B.polys.push({p:pts.slice(), x0:x0, x1:x1, z0:z0, z1:z1, libre:false});
    MURS23B.idx=null;
  }
};
/* un bâtiment que le tracé traverse reste ouvert (porche, portail, passage) */
function traverseParTrace23b(o){
  for(var i=1;i<TRACE.length;i++){
    var a=TRACE[i-1], b=TRACE[i];
    if(Math.max(a[0],b[0])<o.x0-1 || Math.min(a[0],b[0])>o.x1+1 || Math.max(a[1],b[1])<o.z0-1 || Math.min(a[1],b[1])>o.z1+1) continue;
    var L=Math.hypot(b[0]-a[0],b[1]-a[1]), n=Math.max(1,Math.ceil(L/0.5));
    for(var s=0;s<=n;s++){ if(dansPoly(o.p,a[0]+(b[0]-a[0])*s/n, a[1]+(b[1]-a[1])*s/n)) return true; }
  }
  return false;
}
function indexMurs23b(){
  var cle=TRACE.length+':'+Math.round(LONGUEUR||0);
  if(MURS23B.idx && cle===MURS23B.cleTrace) return MURS23B.idx;
  var I={}, C=MURS23B.C;
  MURS23B.polys.forEach(function(o){
    o.libre=traverseParTrace23b(o);
    if(o.libre) return;
    for(var a=Math.floor(o.x0/C);a<=Math.floor(o.x1/C);a++) for(var b=Math.floor(o.z0/C);b<=Math.floor(o.z1/C);b++){ var k=a+','+b; (I[k]||(I[k]=[])).push(o); }
  });
  MURS23B.idx=I; MURS23B.cleTrace=cle;
  return I;
}
var _obst23b=construireObst22;
construireObst22=function(cx,cz){
  _obst23b(cx,cz);
  if(!MURS23B.polys.length) return;
  var I=indexMurs23b(), C=MURS23B.C, R=18, vus=new Set(), L=OBST22.liste;
  for(var a=Math.floor((cx-R)/C);a<=Math.floor((cx+R)/C);a++) for(var b=Math.floor((cz-R)/C);b<=Math.floor((cz+R)/C);b++){
    (I[a+','+b]||[]).forEach(function(o){
      if(vus.has(o)) return;
      vus.add(o);
      if(o.x1<cx-R || o.x0>cx+R || o.z1<cz-R || o.z0>cz+R) return;
      /* rayon négatif : le coureur peut frôler la façade sans y entrer */
      L.push({t:2, p:o.p, r:-MURS23B.marge});
    });
  }
};

/* ----- rubalise : du montant d'entrée au montant de sortie de chaque barrière ----- */
var RUB23B={haut:1.0, montant:1.015, longe:0.035};
/* suite des points de nouage : [entrée, sortie] pour chaque barrière, dans l'ordre de la rubalise */
function cheminRubalise23b(N,angDe){
  var n=N.length, P=[];
  if(n<2) return P;
  for(var k=0;k<n;k++){
    var c=N[k], a=angDe ? angDe(c) : null;
    if(a===null || a===undefined){
      /* barrière inconnue : dans l'axe de la rubalise, comme les barrières d'ancrage */
      var p0=N[Math.max(0,k-1)], p1=N[Math.min(n-1,k+1)];
      a=Math.atan2(p1[1]-p0[1],p1[0]-p0[0])*180/PI;
    }
    var ux=Math.cos(a*PI/180), uz=Math.sin(a*PI/180), m=RUB23B.montant;
    var A=[c[0]+ux*m, c[1]+uz*m], B=[c[0]-ux*m, c[1]-uz*m];
    var ref=k>0 ? N[k-1] : N[1];
    var dA=Math.hypot(A[0]-ref[0],A[1]-ref[1]), dB=Math.hypot(B[0]-ref[0],B[1]-ref[1]);
    /* on arrive par le montant le plus proche de la barrière précédente ; la première
       barrière est longée en entier avant de partir vers la suivante */
    var entree=(k>0) ? (dA<=dB ? A : B) : (dA<=dB ? B : A), sortie=(entree===A) ? B : A;
    var y=hauteurBarriere(c[0],c[1],a)+RUB23B.haut;
    P.push({x:entree[0], z:entree[1], y:y, longe:true}, {x:sortie[0], z:sortie[1], y:y, longe:false});
  }
  return P;
}
/* un brin de rubalise : tendu le long d'une barrière, ou avec un léger ventre entre deux barrières */
function brinRubalise23b(tape,a,b,du,longe){
  var L=Math.hypot(b.x-a.x,b.z-a.z);
  if(L<0.03) return du;
  var blanc=teinte(0xf2f2ee), demi=0.028;
  var nx=-(b.z-a.z)/L, nz=(b.x-a.x)/L, fl=longe ? 0 : Math.min(0.14,0.018*L), S=longe ? 1 : 8, dec=longe ? RUB23B.longe : EQ_DECAL;
  for(var s=0;s<S;s++){
    var t0=s/S, t1=(s+1)/S;
    var x0=a.x+(b.x-a.x)*t0+nx*dec, z0=a.z+(b.z-a.z)*t0+nz*dec;
    var x1=a.x+(b.x-a.x)*t1+nx*dec, z1=a.z+(b.z-a.z)*t1+nz*dec;
    var y0=a.y+(b.y-a.y)*t0-fl*4*t0*(1-t0), y1=a.y+(b.y-a.y)*t1-fl*4*t1*(1-t1);
    var u0=(du+L*t0)/0.9, u1=(du+L*t1)/0.9;
    tape.tri(x0,y0-demi,z0, x1,y1-demi,z1, x1,y1+demi,z1, nx,0,nz,[u0,0,u1,0,u1,1],blanc);
    tape.tri(x0,y0-demi,z0, x1,y1+demi,z1, x0,y0+demi,z0, nx,0,nz,[u0,0,u1,1,u0,1],blanc);
  }
  return du+L;
}
function tapeChemins23b(tape,R,angDe,garder){
  R.forEach(function(r){
    var N=noeudsRubalise(r);
    if(garder) r._noeuds=N;
    var P=cheminRubalise23b(N,angDe), du=0;
    for(var i=1;i<P.length;i++) du=brinRubalise23b(tape,P[i-1],P[i],du,P[i-1].longe);
  });
}
function matTape23b(){
  if(!EQ.matTape){
    EQ.matTape=new THREE.MeshStandardMaterial({map:texRubalise(), side:THREE.DoubleSide, roughness:0.45, metalness:0});
    EQ.matPiq=new THREE.MeshStandardMaterial({vertexColors:true, roughness:0.6, metalness:0});
  }
  return EQ.matTape;
}
construireRubalises=function(){
  if(EQ.rub){ monde.remove(EQ.rub); EQ.rub.children.forEach(function(m){ m.geometry.dispose(); }); EQ.rub=null; }
  var E=CARTE.equip(), R=E.rubalises;
  if(!R.length) return;
  matTape23b();
  /* orientation de la barrière posée à chaque point de nouage */
  var A={};
  E.barrieres.concat(EQ.ancrages||[]).forEach(function(b){
    if(b._x!==undefined) A[b._x.toFixed(2)+','+b._z.toFixed(2)]=b.ang;
  });
  var tape=new Tas(16384);
  tapeChemins23b(tape,R,function(c){ return A[c[0].toFixed(2)+','+c[1].toFixed(2)]; },true);
  var g=new THREE.Group();
  if(!tape.vide()){ var mt=new THREE.Mesh(tape.geo(),EQ.matTape); mt.castShadow=true; g.add(mt); }
  monde.add(g); EQ.rub=g;
};
/* autres parcours affichés : leurs barrières d'ancrage sont dans l'axe de la rubalise */
tapeRubalises=function(R){
  matTape23b();
  var tape=new Tas(16384);
  tapeChemins23b(tape,R,null,false);
  if(tape.vide()) return null;
  var m=new THREE.Mesh(tape.geo(),EQ.matTape);
  m.castShadow=true;
  return m;
};

/* ===== 24. la sono se tait quand « Jeunes Chefs » joue ===== */
/* La sono du départ et de l'arrivée (124 battements par minute) portait à
   380 m, et la 3D s'ouvre au départ : sous la musique, sa grosse caisse et
   son charleston faisaient un « tic » régulier qui ne tombait jamais sur le
   temps de Jeunes Chefs (140). Deux musiques à la fois, c'est une de trop :
   tant que la musique joue, la sono se tait et ne planifie plus rien ; elle
   revient, en fondu, si l'on coupe la musique. Même partition et mêmes
   timbres qu'avant, mais chaque frappe part de zéro en 3 ms au lieu d'un
   départ sec. */
planifierSono=function(){
  var S=SON14.sono, c=SON14.ctx, bpm=124, pas=60/bpm/2, now=c.currentTime;
  if(musiqueActive()){ S.suivant=0; return; }
  if(S.suivant<now) S.suivant=now+0.05;
  var basse=[55,55,65.4,55,49,49,58.3,49,43.7,43.7,52,43.7,49,49,61.7,49];
  while(S.suivant<now+0.5){
    var t=S.suivant, k=S.pas%16;
    if(k%2===0){
      var o=c.createOscillator(), g=c.createGain();
      o.frequency.setValueAtTime(140,t); o.frequency.exponentialRampToValueAtTime(42,t+0.12);
      g.gain.setValueAtTime(0,t); g.gain.linearRampToValueAtTime(0.5,t+0.003); g.gain.exponentialRampToValueAtTime(0.0003,t+0.2);
      o.connect(g); g.connect(S.f); o.start(t); o.stop(t+0.22);
    } else bruitBref(t,'highpass',7000,0.7,0.12,0.04,S.f);
    var ob=c.createOscillator(), gb=c.createGain();
    ob.type='sawtooth'; ob.frequency.value=basse[k]*2;
    gb.gain.setValueAtTime(0,t); gb.gain.linearRampToValueAtTime(0.09,t+0.003); gb.gain.exponentialRampToValueAtTime(0.0003,t+pas*0.9);
    ob.connect(gb); gb.connect(S.f); ob.start(t); ob.stop(t+pas);
    S.suivant+=pas; S.pas++;
  }
};
var _majSons24=majSons;
majSons=function(dt){
  _majSons24(dt);
  var c=SON14.ctx, S=SON14.sono;
  if(c && S && c.state==='running' && musiqueActive()) S.g.gain.setTargetAtTime(0,c.currentTime,0.15);
};
/* une barrière posée à la main qui tient de la rubalise l'emmène quand on la
   déplace, ou qu'on tourne sa rangée */
function liensBarrieres(s){
  var L=[];
  if(s && (s.type==='b' || s.type==='g' || s.type==='m')) elementsSel(s).forEach(function(b){ liensAncrage(b.la,b.lo).forEach(function(x){ L.push([x[0],x[1],b]); }); });
  L.forEach(function(x){ ancrerParBarriere(x[0]); });
  return L;
}
function suivreLiens(L){
  if(!L.length) return;
  L.forEach(function(x){ x[0].pts[x[1]]=[x[2].la,x[2].lo]; });
  CARTE.equipModifie();
}
var _deplacerSel23b=deplacerSel;
deplacerSel=function(s,dx,dz){ var L=liensBarrieres(s); _deplacerSel23b(s,dx,dz); suivreLiens(L); };
var _tournerSel23b=tournerSel;
tournerSel=function(delta){ var L=liensBarrieres(EQ.sel); _tournerSel23b(delta); suivreLiens(L); };

/* ===== 25. monument aux sous-officiers de nuit, faisceaux adoucis, nuit plus claire ===== */
/* Demandes de Nicolas (30 sept. 2026) :
   - deux projecteurs de part et d'autre du monument, allumés la nuit ;
   - le monument garde ses ombres et suit l'ambiance : son léger éclat
     propre (qui le gardait blanc franc en plein jour) baisse au coucher et
     s'éteint la nuit, où seuls les projecteurs le révèlent ;
   - tous les faisceaux (frontales, lampadaires, projecteurs de la tribune
     et du monument) ont un bord fondu au lieu d'une arête franche ;
   - la nuit, d'une teinte plus claire. */

/* ----- la teinte du terrain en un point (grille d'un sommet tous les 5 m) ----- */
function couleurTerrainEn(x,z){
  var C=(typeof meshTerrain!=='undefined' && meshTerrain) ? meshTerrain.geometry.attributes.color : null;
  if(!C || C.count!==GROWS*GCOLS) return [0.33,0.36,0.155];
  var fj=(x-XMIN)/PASX, fi=(ZMAX-z)/PASZ, j0=Math.max(0,Math.min(GCOLS-2,Math.floor(fj))), i0=Math.max(0,Math.min(GROWS-2,Math.floor(fi)));
  var tj=Math.max(0,Math.min(1,fj-j0)), ti=Math.max(0,Math.min(1,fi-i0)), out=[0,0,0];
  [[0,0,(1-ti)*(1-tj)],[0,1,(1-ti)*tj],[1,0,ti*(1-tj)],[1,1,ti*tj]].forEach(function(q){
    var k=(i0+q[0])*GCOLS+j0+q[1];
    out[0]+=C.getX(k)*q[2]; out[1]+=C.getY(k)*q[2]; out[2]+=C.getZ(k)*q[2];
  });
  return out;
}

/* ----- un faisceau au bord fondu ----- */
/* Une surface additive vue par la tranche dessine une arête nette. On
   atténue la lumière là où la surface est vue de biais (bord du cône) et,
   si demandé, vers le bout du faisceau (uv.v qui tend vers 0). */
function adoucirFaisceau(m,bout){
  if(!m || m.userData.doux25) return m;
  m.userData.doux25=true;
  var ob=m.onBeforeCompile;
  m.onBeforeCompile=function(sh){
    if(ob) ob.call(this,sh);
    sh.vertexShader=sh.vertexShader
      .replace('#include <common>','#include <common>\nvarying vec3 vN25;\nvarying vec3 vV25;\nvarying float vL25;')
      .replace('#include <project_vertex>','#include <project_vertex>\nvN25=normalize(normalMatrix*normal);\nvV25=-mvPosition.xyz;\n'+(bout?'vL25=uv.y;':'vL25=1.0;'));
    var fin='float f25=abs(dot(normalize(vN25),normalize(vV25)));\nf25=smoothstep(0.0,0.75,f25);\n'+
            (bout?'f25*=smoothstep(0.0,0.4,vL25);\n':'')+'outgoingLight*=f25;\ndiffuseColor.a*=f25;\n';
    if(sh.fragmentShader.indexOf('#include <opaque_fragment>')>=0)
      sh.fragmentShader=sh.fragmentShader.replace('#include <opaque_fragment>',fin+'#include <opaque_fragment>');
    else sh.fragmentShader=sh.fragmentShader.replace('#include <output_fragment>',fin+'#include <output_fragment>');
    sh.fragmentShader=sh.fragmentShader.replace('#include <common>','#include <common>\nvarying vec3 vN25;\nvarying vec3 vV25;\nvarying float vL25;');
  };
  var ck=m.customProgramCacheKey;
  m.customProgramCacheKey=function(){ return (ck?ck.call(this):'')+'|doux25'+(bout?'b':''); };
  m.needsUpdate=true;
  return m;
}

/* frontales : faisceau fondu sur les bords et au bout, tache au sol sans bord net */
var _initFront25=initFrontales;
initFrontales=function(){
  var r=_initFront25.apply(this,arguments);
  try{
    adoucirFaisceau(FRONT.matFaisceau,true);
    FRONT.spots.forEach(function(s){ s.penumbra=1; });
  }catch(e){}
  return r;
};

/* cônes des lampadaires : refaits avec un sommet par pan, chacun avec la
   normale de son pan, pour que le bord du cône puisse s'effacer */
var _cones25=etapeCones;
etapeCones=function(){
  var r=_cones25.apply(this,arguments);
  try{
    if(!NUIT14.cones || typeof lampes==='undefined') return r;
    var seg=16, pos=[], col=[], nor=[];
    lampes.forEach(function(L){
      var x=L[0], y=L[1], z=L[2], ys=hauteur(x,z)+0.04, R=2.7, h=(y-0.12)-ys;
      for(var i=0;i<seg;i++){
        var a0=i/seg*2*PI, a1=(i+1)/seg*2*PI, am=(a0+a1)/2;
        /* normale du pan : horizontale vers l'extérieur, un peu relevée */
        var nx=Math.cos(am)*h, nz=Math.sin(am)*h, ny=R, ln=Math.hypot(nx,ny,nz);
        pos.push(x,y-0.12,z, x+Math.cos(a0)*R,ys,z+Math.sin(a0)*R, x+Math.cos(a1)*R,ys,z+Math.sin(a1)*R);
        col.push(0.1,0.078,0.046, 0,0,0, 0,0,0);
        for(var k=0;k<3;k++) nor.push(nx/ln,ny/ln,nz/ln);
      }
    });
    var g=new THREE.BufferGeometry();
    g.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));
    g.setAttribute('color',new THREE.Float32BufferAttribute(col,3));
    g.setAttribute('normal',new THREE.Float32BufferAttribute(nor,3));
    NUIT14.cones.geometry.dispose(); NUIT14.cones.geometry=g;
    adoucirFaisceau(NUIT14.cones.material,false);
  }catch(e){ console.warn('cônes doux :',e); }
  return r;
};

/* projecteurs de la tribune : chaque faisceau plat reçoit un profil en
   cloche sur sa largeur (noir aux bords, plein au centre) */
var _trico25=etapeTricolore;
etapeTricolore=function(){
  var r=_trico25.apply(this,arguments);
  try{
    var fa=null;
    TRICOLORE.projos.children.forEach(function(o){ if(o.isMesh && o.material.vertexColors && o.material.blending===THREE.AdditiveBlending) fa=o; });
    if(!fa) return r;
    var P=fa.geometry.attributes.position, C=fa.geometry.attributes.color, nb=P.count/4, pos=[], col=[], idx=[];
    var W=[0,0.35,0.8,1,0.8,0.35,0], nc=W.length;
    function v(i){ return [P.getX(i),P.getY(i),P.getZ(i)]; }
    function c(i){ return [C.getX(i),C.getY(i),C.getZ(i)]; }
    function lerp(a,b,t){ return [a[0]+(b[0]-a[0])*t,a[1]+(b[1]-a[1])*t,a[2]+(b[2]-a[2])*t]; }
    for(var s=0;s<nb;s++){
      var BL=v(s*4), BR=v(s*4+1), TR=v(s*4+2), TL=v(s*4+3), c0=c(s*4), c1=c(s*4+2), base=pos.length/3;
      for(var k=0;k<nc;k++){
        var t=k/(nc-1), b=lerp(BL,BR,t), h=lerp(TL,TR,t);
        pos.push(b[0],b[1],b[2], h[0],h[1],h[2]);
        col.push(c0[0]*W[k],c0[1]*W[k],c0[2]*W[k], c1[0]*W[k],c1[1]*W[k],c1[2]*W[k]);
      }
      for(k=0;k<nc-1;k++){ var a=base+k*2; idx.push(a,a+2,a+3, a,a+3,a+1); }
    }
    var g=new THREE.BufferGeometry();
    g.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));
    g.setAttribute('color',new THREE.Float32BufferAttribute(col,3));
    g.setIndex(idx);
    fa.geometry.dispose(); fa.geometry=g;
  }catch(e){ console.warn('faisceaux tribune :',e); }
  return r;
};

/* ----- deux projecteurs pour le monument aux sous-officiers ----- */
/* Pas de vraies lampes (elles pèseraient sur tous les matériaux de la
   ville) : leur lumière est calculée dans le seul shader du monument et
   dans celui du terrain, avec l'angle de chaque face, donc avec ses ombres
   propres : une face tournée vers le projecteur s'éclaire, l'autre reste
   dans le noir. */
var SPOT25={u:{uSpP:{value:[new THREE.Vector3(),new THREE.Vector3()]}, uSpD:{value:[new THREE.Vector3(0,-1,0),new THREE.Vector3(0,-1,0)]},
  uSpI:{value:0}, uSpCol:{value:new THREE.Color(1.0,0.9,0.76)}, uSpC:{value:new THREE.Vector2(Math.cos(0.62),Math.cos(0.30))}},
  grp:null, force:15};
function eclairerParSpots25(m){
  if(!m || m.userData.spot25) return;
  m.userData.spot25=true;
  var ob=m.onBeforeCompile;
  m.onBeforeCompile=function(sh){
    if(ob) ob.call(this,sh);
    Object.keys(SPOT25.u).forEach(function(k){ sh.uniforms[k]=SPOT25.u[k]; });
    sh.fragmentShader=sh.fragmentShader
      .replace('#include <common>','#include <common>\nuniform vec3 uSpP[2];\nuniform vec3 uSpD[2];\nuniform float uSpI;\nuniform vec3 uSpCol;\nuniform vec2 uSpC;')
      .replace('#include <lights_fragment_end>',[
        '#include <lights_fragment_end>',
        'if(uSpI>0.0){',
        '  for(int s25=0;s25<2;s25++){',
        '    vec3 lp25=(viewMatrix*vec4(uSpP[s25],1.0)).xyz;',
        '    vec3 ld25=normalize((viewMatrix*vec4(uSpD[s25],0.0)).xyz);',
        '    vec3 L25=lp25+vViewPosition; float d25=length(L25); L25/=max(d25,1e-3);',
        '    float cone25=smoothstep(uSpC.x,uSpC.y,dot(-L25,ld25));',
        '    float att25=uSpI/(1.0+d25*d25*0.012);',
        '    reflectedLight.directDiffuse+=uSpCol*(att25*cone25*max(dot(normal,L25),0.0))*BRDF_Lambert(material.diffuseColor);',
        '  }',
        '}'].join('\n'));
  };
  var ck=m.customProgramCacheKey;
  m.customProgramCacheKey=function(){ return (ck?ck.call(this):'')+'|spot25'; };
  m.needsUpdate=true;
}
function etapeSpotsMSO(){
  if(!MSO.pos || !MSO.ins) return;
  var arc=arcMSO([MSO.ins[0],0,MSO.ins[1]],MSO.R,MSO.N,MSO.rArc), top=hauteur(MSO.pos[0],MSO.pos[1])+2.6;
  var cible=new THREE.Vector3(MSO.pos[0],top+1.8,MSO.pos[1]);
  var grp=new THREE.Group(), corps=new THREE.MeshStandardMaterial({color:0x23272d, roughness:0.55, metalness:0.5});
  var verre=new THREE.MeshBasicMaterial({color:0xfff1d6});
  var faisceau=adoucirFaisceau(new THREE.MeshBasicMaterial({color:0xffe9c8, transparent:true, opacity:0.035,
    blending:THREE.AdditiveBlending, depthWrite:false, side:THREE.DoubleSide}),true);
  var geoF=new THREE.CylinderGeometry(0.12,3.4,1,24,1,true); geoF.translate(0,-0.5,0);
  var bas=new THREE.Vector3(0,-1,0);
  [-1,1].forEach(function(s,k){
    var u=s*(MSO.largeur/2+1.2), p=arc.P(u,0.7), y=hauteur(p[0],p[1]);
    var lampe=new THREE.Vector3(p[0],y+0.42,p[1]), dir=cible.clone().sub(lampe), L=dir.length(); dir.divideScalar(L);
    SPOT25.u.uSpP.value[k].copy(lampe); SPOT25.u.uSpD.value[k].copy(dir);
    /* le projecteur : un pied court, un boîtier tourné vers la sculpture, la vitre allumée */
    var pied=new THREE.Mesh(new THREE.CylinderGeometry(0.035,0.05,0.3,8),corps); pied.position.set(p[0],y+0.15,p[1]); grp.add(pied);
    var boite=new THREE.Mesh(new THREE.BoxGeometry(0.34,0.26,0.3),corps);
    boite.position.copy(lampe); boite.quaternion.setFromUnitVectors(new THREE.Vector3(0,0,1),dir); grp.add(boite);
    var vitre=new THREE.Mesh(new THREE.CircleGeometry(0.11,20),verre);
    vitre.position.copy(lampe).addScaledVector(dir,0.152); vitre.quaternion.copy(boite.quaternion); grp.add(vitre);
    var halo=spriteLueur(0xfff0d0,0.9); halo.position.copy(lampe).addScaledVector(dir,0.2); grp.add(halo);
    /* le faisceau dans l'air, fondu sur les bords et vers le bout */
    var f=new THREE.Mesh(geoF,faisceau);
    f.position.copy(lampe).addScaledVector(dir,0.16);
    f.quaternion.setFromUnitVectors(bas,dir); f.scale.set(1,L*0.95,1);
    f.renderOrder=9; grp.add(f);
  });
  grp.name='projecteurs du monument';
  SPOT25.grp=grp; monde.add(grp);
  eclairerParSpots25(MSO.mat);
  if(MAT.terrain) eclairerParSpots25(MAT.terrain);
  ambiance25();
}
ETAPES.forEach(function(e,i){ if(e[0]==='Monument aux sous-officiers') ETAPES.splice(i+1,0,['Projecteurs du monument',function(){ try{ etapeSpotsMSO(); }catch(e){ console.warn('projecteurs monument :',e); } }]); });

/* ----- l'ambiance : monument, projecteurs, nuit ----- */
/* d'une teinte plus claire la nuit : exposition et ciel un peu relevés */
var NUIT25={expo:1.2, hemi:1.4, env:1.25};
var ECLAT25={midi:1, matin:0.8, soir:0.55, coucher:0.3};
function ambiance25(){
  if(MSO.mat) MSO.mat.emissiveIntensity=nuit?0:(ECLAT25[MOMENT.cle]!==undefined?ECLAT25[MOMENT.cle]:1);
  SPOT25.u.uSpI.value=nuit?SPOT25.force:0;
  if(SPOT25.grp){
    SPOT25.grp.visible=true;
    SPOT25.grp.children.forEach(function(o){ if(!(o.isMesh && o.material.isMeshStandardMaterial)) o.visible=!!nuit; });
  }
}
var _ciel25=appliquerCiel;
appliquerCiel=function(){
  var r=_ciel25.apply(this,arguments);
  try{
    if(nuit && renderer && lumSol){
      renderer.toneMappingExposure*=NUIT25.expo;
      lumSol.intensity*=NUIT25.hemi;
      if(scene) scene.environmentIntensity=(scene.environmentIntensity||0)*NUIT25.env;
    }
    ambiance25();
  }catch(e){}
  return r;
};
/* ===== 26. ouverture rapide : la ville d'abord, le monde ensuite ===== */
/* Les modèles arrivent en vrais fichiers (adresses blob:, voir le chargeur
   de index.html). Les piétons, les coureurs d'ambiance et le chien sont
   téléchargés en arrière-plan (ACTIFS_DIFFERES) : leurs deux étapes de
   construction sont retirées de la mise en place et jouées juste après
   l'ouverture de la vue. Tout ce qui les anime attend déjà qu'ils soient
   prêts (VIE.pret, FOULE.pret), la ville se peuple donc d'elle-même. */
if(window.ACTIFS_DIFFERES){
  var DIFFERES24=[];
  for(var i24=ETAPES.length-1;i24>=0;i24--){
    if(ETAPES[i24][0]==='Piétons et gestes des jalonneurs' || ETAPES[i24][0]==='Coureurs et spectateurs'){ DIFFERES24.unshift(ETAPES[i24]); ETAPES.splice(i24,1); }
  }
  var lance24=false;
  var _demarrerBoucle24=demarrerBoucle;
  demarrerBoucle=function(){
    _demarrerBoucle24();
    if(!lance24 && construit){ lance24=true; setTimeout(peuplerVille24,300); }
  };
  var peuplerVille24=function(){
    ACTIFS_DIFFERES.then(function(){
      return DIFFERES24.reduce(function(p,e){
        return p.then(function(){ return new Promise(function(ok){ setTimeout(ok,50); }); })
                .then(function(){ return e[1](); })
                .catch(function(err){ console.warn(e[0],err); });
      },Promise.resolve());
    }).then(function(){
      /* le peloton formé avant l'arrivée des modèles était vide : il se reformera */
      if(typeof PELOTON!=='undefined' && PELOTON.actif && !PELOTON.gens.length) PELOTON.actif=false;
      /* sur iPhone, les avatars montés n'ont plus besoin de leur fichier */
      if(SUR_IOS_3D){
        var A=window.ACTIFS||{};
        Object.keys(A).forEach(function(k){ var v=A[k]; if(typeof v==='string' && v.indexOf('blob:')===0 && /\.fbx$/i.test(k) && !/^Police_/i.test(k)){ URL.revokeObjectURL(v); delete A[k]; } });
      }
    });
  };
  /* le chien attend son modèle s'il n'est pas encore arrivé */
  var _chien24=chargerModeleChien;
  chargerModeleChien=function(){
    if(window.ACTIFS && !ACTIFS['chien_berger.glb']) return ACTIFS_DIFFERES.then(function(){ return _chien24(); });
    return _chien24();
  };
}
/* une fois la ville bâtie, les photos et le ciel ne servent plus : on rend leur mémoire */
var _libererActifs24=libererActifs;
libererActifs=function(){
  var A=window.ACTIFS||{}, n=0;
  Object.keys(A).forEach(function(k){
    var v=A[k];
    if(typeof v!=='string' || v.indexOf('blob:')!==0) return;
    if(/^(ph2?|hd)_/.test(k) || k==='ciel_jour.hdr'){ URL.revokeObjectURL(v); delete A[k]; n++; }
  });
  return _libererActifs24()+n;
};

