      var lfo=c.createOscillator(), lg=c.createGain(); lfo.frequency.value=5.3; lg.gain.value=f*0.005; lfo.connect(lg); lg.connect(o.frequency);
      lp.type='lowpass'; lp.Q.value=1.8;
