  if(VEST.cadre==='visage' && !VEST.glisse && Math.abs(VEST.vRot)<0.3){ var face=-PI/2+Math.round((VEST.rot+PI/2)/(2*PI))*2*PI; VEST.rot+=(face-VEST.rot)*Math.min(1,dt*4); }
